sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_wipeType;
uniform float amzp_reverse;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_softness;
uniform float amzp_edgeNoise;
uniform float amzp_noiseSize;
uniform float amzp_partSize;
uniform float amzp_life;
uniform float amzp_flyDist;
uniform float amzp_windDir;
uniform float amzp_speedVar;
uniform float amzp_turb;
uniform float amzp_rise;
uniform float amzp_shrink;
uniform float amzp_edgeGlow;
layout(color) uniform half4 amzp_edgeCol;
uniform float amzp_dustTint;
layout(color) uniform half4 amzp_dustCol;
uniform float amzp_partBright;
uniform float amzp_samples;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_center;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 h4(float2 c) {
        float4 p = float4(dot(c, float2(127.1, 311.7)), dot(c, float2(269.5, 183.3)), dot(c, float2(419.2, 371.9)), dot(c, float2(91.7, 57.3)));
        return fract(sin(p) * 43758.5453);
    }
    float vnoise(float2 x) {
        float2 i = floor(x), f = x - i;
        f = f * f * (3.0 - 2.0 * f);
        float a = h4(i).x, b = h4(i + float2(1.0, 0.0)).x, c = h4(i + float2(0.0, 1.0)).x, d = h4(i + float2(1.0, 1.0)).x;
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }
    float fbm(float2 x) { return 0.55 * vnoise(x) + 0.3 * vnoise(x * 2.03 + 7.1) + 0.15 * vnoise(x * 4.1 + 3.3); }
    float wipeAt(float2 c, float2 L) {
        float minS = min(L.x, L.y);
        float w;
        if (int(amzp_wipeType) == 0) {
            float a = radians(amzp_angle);
            float2 d = float2(cos(a), sin(a));
            float ext = 0.5 * (abs(d.x) * L.x + abs(d.y) * L.y);
            w = dot(c - 0.5 * L, d) / max(ext, 1.0) * 0.5 + 0.5;
        } else if (int(amzp_wipeType) == 1) {
            float2 cc = 0.5 * L + amzp_center;
            float rmax = length(max(abs(cc), abs(L - cc)));
            w = length(c - cc) / max(rmax, 1.0);
        } else w = 0.5;
        float n = fbm(c / (max(amzp_noiseSize, 1.0) * max(amzp_scale * 2.0, 0.01)));
        float en = int(amzp_wipeType) == 2 ? 1.0 : clamp(amzp_edgeNoise, 0.0, 1.0);
        return clamp(mix(w, n, en), 0.0, 1.0);
    }
    float2 flight(float2 c, float u, float4 r, bool mean) {
        float a = radians(amzp_windDir);
        float2 dir = float2(cos(a), -sin(a));
        float2 nrm = float2(-dir.y, dir.x);
        float sv = mean ? 1.0 : 1.0 + amzp_speedVar * (r.y - 0.5) * 2.0;
        float e = u * (0.35 + 0.65 * u);
        float2 d = dir * amzp_flyDist * e * sv;
        float ns = max(amzp_noiseSize, 1.0) * 2.0;
        d += nrm * amzp_turb * u * (vnoise(c / ns + float2(u * 2.0, 0.0)) - 0.5) * 2.0;
        d += float2(0.0, -amzp_rise) * u * u;
        if (!mean) d += (r.zw - 0.5) * u * amzp_partSize * 3.0;
        return d;
    }
    void amzRender() {
        float2 L = layer;
        float2 p = float2(amzLayerNorm().x, 1.0 - amzLayerNorm().y) * L;
        float lifeP = max(amzp_life, 0.02);
        float total = 1.0 + lifeP;
        float pr = clamp(amzp_progress + ((amzp_autop>0.5) ? time * amzp_autoSpeed * 0.33 : 0.0), 0.0, 1.0);
        float P = ((amzp_reverse>0.5) ? 1.0 - pr : pr) * total;
        float soft = max(amzp_softness, 0.002);
        float wp = wipeAt(p, L);
        float keep = 1.0 - smoothstep(wp - soft, wp, P);
        float4 base = amzTexture(0, amzScreenNorm()) * keep;
        float band = exp(-pow((P - wp) / (soft * 0.6 + 0.006), 2.0)) * keep;
        float cs = max(amzp_partSize, 1.0);
        float4 dust = float4(0.0);
        float S = clamp(floor(amzp_samples + 0.5), 1.0, 40.0);
        for (int i = 0; i < 40; i++) {
            float fi = float(i);
            if (fi >= S) break;
            float ui = (fi + 0.5) / S;
            float2 src = p - flight(p, ui, float4(0.5), true);
            src = p - flight(src, ui, float4(0.5), true);
            float2 cell = floor(src / cs);
            float2 cc = (cell + 0.5) * cs;
            if (cc.x < 0.0 || cc.y < 0.0 || cc.x > L.x || cc.y > L.y) continue;
            float u = (P - wipeAt(cc, L)) / lifeP;
            if (u <= 0.0 || u >= 1.0) continue;
            float4 r = h4(cell + 17.0);
            float2 amzLocal_pos = cc + flight(cc, u, r, false);
            float rad = 0.5 * cs * (1.0 - amzp_shrink * u) + 0.35;
            float cov = 1.0 - smoothstep(rad - 0.6, rad + 0.6, length(p - amzLocal_pos));
            if (cov <= 0.0) continue;
            float4 sc = amzTexture(0, l2s(float2(cc.x / L.x, 1.0 - cc.y / L.y)));
            if (sc.a < 0.02) continue;
            float3 col = sc.rgb / sc.a;
            col = mix(col, amzp_dustCol.rgb, amzp_dustTint);
            col += amzp_edgeCol.rgb * amzp_edgeGlow * (1.0 - smoothstep(0.0, 0.3, u)) * 0.8;
            float a = cov * sc.a * (1.0 - u * u) * (0.75 + 0.25 * r.x);
            dust.rgb += clamp(col * amzp_partBright, 0.0, 1.0) * a * (1.0 - dust.a);
            dust.a += a * (1.0 - dust.a);
        }
        float4 lay = base;
        lay.rgb += amzp_edgeCol.rgb * amzp_edgeGlow * band * base.a;
        float4 o = dust + lay * (1.0 - dust.a);
        o = clamp(o, 0.0, 1.0);
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
